tooltip:
{{
  (() => {
    const movs = get_saldo_ciclos_anteriores.data || [];
    if (movs.length === 0) return "No tienes cargos ni abonos pendientes de ciclos anteriores.";

    return movs.map(m => {
      const signo = m.tipo === 'cargo' ? '+' : '-';
      const valor = Number(m.monto).toLocaleString('es-CL', { style: 'currency', currency: 'CLP' });
      const etiqueta = m.tipo === 'cargo' ? 'Cargo' : 'Abono';
      return `• ${etiqueta} (${signo}${valor}): ${m.descripcion}`;
    }).join('\n');
  })()
}}
